-- Read-only existing policy and deterministic execution review; no automation authoring authority.
begin;
create index outbox_school_window_review on internal.outbox_events(school_id,occurred_at desc,id desc);
create function internal.read_school_automation()returns jsonb language plpgsql stable security definer set search_path=''as $$
declare school uuid:="authorization".school_id();ends timestamptz:=clock_timestamp();starts timestamptz:=ends-interval'7 days';state_policy app.learner_state_policies;attention app.attention_policies;recognition app.recognition_policies;privacy app.school_policy_versions;communication app.parent_conversation_policies;intelligence app.intelligence_policies;policies jsonb;entries jsonb;counts jsonb;clipped boolean;execution_bound boolean;empty_conditions jsonb;
begin
 if not"authorization".can_access_school(school)or not"authorization".has_entitlement(school,'school.operations')or"authorization".current_role(school)is distinct from'admin'then raise exception 'Administrator automation review denied'using errcode='42501';end if;
 select p.*into state_policy from app.learner_state_policies p where p.school_id=school;
 select p.*into attention from app.attention_policies p where p.school_id=school order by p.version desc limit 1;
 select p.*into recognition from app.recognition_policies p where p.school_id=school order by p.version desc limit 1;
 select p.*into privacy from app.school_policy_versions p where p.school_id=school order by p.version desc limit 1;
 select p.*into communication from app.parent_conversation_policies p where p.school_id=school order by p.version desc limit 1;
 select p.*into intelligence from app.intelligence_policies p where p.school_id=school;
 execution_bound:=coalesce((select b.policy_version=intelligence.version and b.effective_at<=now()from internal.intelligence_execution_bindings b where b.school_id=school order by b.version desc limit 1),false);
 empty_conditions:=jsonb_build_object('windowDays',null,'minimumDecline',null,'maxScore',null,'missingDueCount',null,'practicePoints',null,'revisionPoints',null,'reflectionPoints',null,'parentCommunicationEnabled',null,'fixtureEnabled',null,'liveEnabled',null,'executionConfigured',null);
 policies:=jsonb_build_array(
  jsonb_build_object('id','LEARNER_STATE','version',state_policy.version,'configured',state_policy.school_id is not null,'enabled',state_policy.school_id is not null and"authorization".has_entitlement(school,'learner.state'),'approvedBy',(select p.display_name from app.people p where p.school_id=school and p.actor_id=state_policy.approved_by),'approvedAt',null,'conditions',empty_conditions||jsonb_build_object('windowDays',state_policy.development_window_days)),
  jsonb_build_object('id','ATTENTION','version',attention.version,'configured',attention.id is not null,'enabled',attention.id is not null and"authorization".has_entitlement(school,'learner.state'),'approvedBy',(select p.display_name from app.people p where p.school_id=school and p.actor_id=attention.approved_by),'approvedAt',attention.approved_at,'conditions',empty_conditions||jsonb_build_object('windowDays',attention.window_days,'minimumDecline',attention.minimum_decline,'maxScore',attention.max_score,'missingDueCount',attention.missing_due_count)),
  jsonb_build_object('id','RECOGNITION','version',recognition.version,'configured',recognition.id is not null,'enabled',recognition.id is not null and coalesce(privacy.recognition_enabled,false)and"authorization".has_entitlement(school,'learner.state'),'approvedBy',(select p.display_name from app.people p where p.school_id=school and p.actor_id=recognition.approved_by),'approvedAt',recognition.approved_at,'conditions',empty_conditions||jsonb_build_object('practicePoints',recognition.practice_points,'revisionPoints',recognition.revision_points,'reflectionPoints',recognition.reflection_points)),
  jsonb_build_object('id','COMMUNICATION','version',communication.version,'configured',communication.id is not null,'enabled',communication.id is not null and communication.enabled and"authorization".has_entitlement(school,'community'),'approvedBy',(select p.display_name from app.people p where p.school_id=school and p.actor_id=communication.approved_by),'approvedAt',communication.approved_at,'conditions',empty_conditions||jsonb_build_object('parentCommunicationEnabled',coalesce(communication.enabled,false))),
  jsonb_build_object('id','INTELLIGENCE','version',intelligence.version,'configured',intelligence.school_id is not null,'enabled',intelligence.school_id is not null and execution_bound and(intelligence.fixture_enabled or intelligence.live_enabled)and"authorization".has_entitlement(school,'improvement'),'approvedBy',(select p.display_name from app.people p where p.school_id=school and p.actor_id=intelligence.approved_by),'approvedAt',intelligence.approved_at,'conditions',empty_conditions||jsonb_build_object('fixtureEnabled',coalesce(intelligence.fixture_enabled,false),'liveEnabled',coalesce(intelligence.live_enabled,false),'executionConfigured',execution_bound)));
 with candidates as materialized(
  select e.id,e.type,e.state,e.attempt_count,e.occurred_at,e.completed_at,e.last_error_code from internal.outbox_events e where e.school_id=school and e.occurred_at>=starts and e.occurred_at<=ends and e.type in('activity.complete','submission.create','submission.resubmitted','quiz.submitted','result.released','rubric.result.released','learner_state.updated','attention.updated','habit.observed','development.updated','community.post_created','community.changed','moderation.reported','community.mention.read','parent-conversation.changed','community.maintenance.changed')order by e.occurred_at desc,e.id desc limit 2001
 ),bounded as materialized(select*from candidates order by occurred_at desc,id desc limit 2000),receipts as materialized(select pe.event_id from internal.processed_events pe where pe.school_id=school and pe.event_id in(select id from bounded)union select receipt.event_id from internal.community_broadcast_receipts receipt join bounded b on b.id=receipt.event_id),stats as(select count(*)returned,count(*)filter(where state='PENDING')pending,count(*)filter(where state='PROCESSING')processing,count(*)filter(where state='COMPLETED')completed,count(*)filter(where state='FAILED')failed,count(*)filter(where attempt_count>1)retried,count(*)filter(where state='COMPLETED'and id in(select event_id from receipts))receipt_count,max(completed_at)filter(where state='COMPLETED'and id in(select event_id from receipts))latest_completion_at from bounded),recent as(select*from bounded order by occurred_at desc,id desc limit 25)
 select jsonb_build_object('scope','RETURNED_ALLOWLIST_EVENTS_IN_WINDOW','returned',stats.returned,'truncated',(select count(*)from candidates)>2000,'pending',stats.pending,'processing',stats.processing,'completed',stats.completed,'failed',stats.failed,'retried',stats.retried,'receiptCount',stats.receipt_count,'latestCompletionAt',stats.latest_completion_at,'runs',(select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'family',case when e.type in('activity.complete','submission.create','submission.resubmitted','quiz.submitted')then'LEARNING_SOURCE'when e.type in('result.released','rubric.result.released')then'ACADEMIC_RELEASE'when e.type='learner_state.updated'then'LEARNER_STATE'when e.type='attention.updated'then'ATTENTION'when e.type in('habit.observed','development.updated')then'RECOGNITION'else'COMMUNICATION'end,'state',e.state,'attemptCount',e.attempt_count,'occurredAt',e.occurred_at,'completedAt',e.completed_at,'receiptRecorded',e.state='COMPLETED'and e.id in(select event_id from receipts),'error',case when e.last_error_code is null then null when e.last_error_code='LEASE_EXHAUSTED'then'LEASE_EXHAUSTED'when e.last_error_code='PROCESSING_REQUIRES_REVIEW'then'REQUIRES_REVIEW'else'OTHER_FAILURE'end)order by e.occurred_at desc,e.id desc),'[]'::jsonb)from recent e))into counts from stats;
 return jsonb_build_object('windowStart',starts,'windowEnd',ends,'policies',policies,'execution',counts,'approvals','EXISTING_HUMAN_APPROVALS_UNCHANGED');
end$$;
revoke execute on function internal.read_school_automation()from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.read_school_automation()to cuevo_api;
commit;




